import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0007: 为什么使用 SQLite","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0007-why-sqlite.md","filePath":"zh/adr/ADR-0007-why-sqlite.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0007-why-sqlite.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0007-为什么使用-sqlite" tabindex="-1">ADR-0007: 为什么使用 SQLite <a class="header-anchor" href="#adr-0007-为什么使用-sqlite" aria-label="Permalink to “ADR-0007: 为什么使用 SQLite”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：docs/guide/persistence.md §7</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>Custos 是本地优先引擎：断网时必须继续工作（事件入队、状态持久化）， 崩溃后必须能恢复未完成的恢复任务；用户不应被要求先装一个数据库服务。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>SQLite（WAL 模式，<code>libsqlite3-sys</code> bundled 保证各平台从源码构建）： 单一文件、零运维、事务满足崩溃一致性写序；custos-store 提供版本化迁移 （<code>schema_migrations</code>，迁移只增不改历史）与 sync 门面（引擎保持同步模型）。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>PostgreSQL/MySQL</strong>：需要外部服务，违背本地优先；断网即失忆。</li><li><strong>JSON 文件</strong>：无事务，崩溃窗口内丢事实；无索引，审计查询退化。</li><li><strong>嵌入式 KV（sled/redb）</strong>：成熟度与查询能力不足，审计检索要自建。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：部署即文件；事务让&quot;执行前持久化 attempt&quot;（ADR-0008）有原子性； SQL 审计与 CLI 的 status/runs/incidents/notify 查询直达。 缺点：单写者（WAL + 单连接足够：一个引擎进程）；大表需保留期清理（§7.4 已实现）。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>所有持久化走 custos-store；迁移 V1→V3 已有，schema 变更必须新版本号。</li><li>通知队列（五状态）与恢复状态共用同一 SQLite 文件，断网补发天然成立。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};